10: contract C0002Policy {
11:   address public immutable router;
12:   address public immutable administrator;
13:   uint256 public limit;
14:   mapping(address => uint256) public routed;
15:   constructor(address router_, uint256 initialLimit) { router = router_; administrator = msg.sender; limit = initialLimit; }
16:   function lowerLimit(uint256 next) external {
17:     require(msg.sender == administrator, "administrator only");
18:     require(next < limit, "not lower");
19:     limit = next;
20:   }
